def in_play(r, c):
    return 1 <= r <= 8 and 1 <= c <= 8

def push_score(B, G, d):
    """Linearized score for action d pushing box at B toward/away from G."""
    dr, dc = delta[d]
    Ar, Ac = B[0] - dr, B[1] - dc
    if not in_play(Ar, Ac):
        return None
    Br2, Bc2 = B[0] + dr, B[1] + dc
    if not in_play(Br2, Bc2):
        return None
    return E[Ar, Ac, 0, d] + E[B[0], B[1], 1, d] + E[G[0], G[1], 2, d]

# Paired comparison: toward push vs opposite (away) push, nearest goal
