import numpy as np

W1, W2, W3 = W['W1'], W['W2'], W['W3']
E = W1 @ W2 @ W3  # linear effective logits per input cell/channel: (500,5)

def eff(r, c, ch):
    return E[(r * 10 + c) * 5 + ch]

playable = [(r, c) for r in range(1, 9) for c in range(1, 9)]
actions = {1: (-1, 0), 2: (1, 0), 3: (0, -1), 4: (0, 1)}

def valid_actions(r, c):
    va = []
    for a, (dr, dc) in actions.items():
        nr, nc = r + dr, c + dc
        if 1 <= nr <= 8 and 1 <= nc <= 8:
            va.append(a)
    return va

def new_pos(r, c, a):
    dr, dc = actions[a]
    return r + dr, c + dc

def manh(p, q):
    return abs(p[0] - q[0]) + abs(p[1] - q[1])

for ch, name in [(1, 'ch1'), (2, 'ch2')]:
    diffs = []
    bins = {1: [], 2: [], 3: [], 4: []}
    for A in playable:
        va = valid_actions(*A)
        base_scores = eff(*A, 0)
        base_action = max(va, key=lambda a: base_scores[a])
        base_pos = new_pos(*A, base_action)
        for O in playable:
            if O == A:
                continue
            d = manh(A, O)
            b = min(d, 4)
            comb_scores = base_scores + eff(*O, ch)
            comb_action = max(va, key=lambda a: comb_scores[a])
            comb_pos = new_pos(*A, comb_action)
            diff = manh(comb_pos, O) - manh(base_pos, O)
            diffs.append(diff)
            bins[b].append(diff)
    diffs = np.array(diffs)
    print(f"=== {name} ===")
    print(f"overall mean diff = {diffs.mean():.3f}, frac diff>0 (away from O) = {(diffs>0).mean():.3f}, frac diff<0 (toward O) = {(diffs<0).mean():.3f}")
    for b in sorted(bins):
        arr = np.array(bins[b])
        label = f"{b}+" if b == 4 else str(b)
        print(f"dist {label}: n={len(arr)}, mean={arr.mean():.3f}, frac>0={ (arr>0).mean():.3f}, frac<0={ (arr<0).mean():.3f}")
